contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        uint64 oldNumber = c.number(); if (__ESBMC_reverted()) return;
        uint64 oldTimestamp = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 oldBasefee = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 oldHash = c.hash(); if (__ESBMC_reverted()) return;
        uint64 oldSequenceNumber = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 oldBatcherHash = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 oldL1FeeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 oldL1FeeScalar = c.l1FeeScalar(); if (__ESBMC_reverted()) return;

        bool reverted = false;
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            reverted &&
            c.number() == oldNumber &&
            c.timestamp() == oldTimestamp &&
            c.basefee() == oldBasefee &&
            c.hash() == oldHash &&
            c.sequenceNumber() == oldSequenceNumber &&
            c.batcherHash() == oldBatcherHash &&
            c.l1FeeOverhead() == oldL1FeeOverhead &&
            c.l1FeeScalar() == oldL1FeeScalar
        );
    }

    receive() external payable {}
}

