        uint64 oldNumber;
        try c.number() returns (uint64 __r) { oldNumber = __r; } catch { return; }
        uint64 oldTimestamp;
        try c.timestamp() returns (uint64 __r) { oldTimestamp = __r; } catch { return; }
        uint256 oldBasefee;
        try c.basefee() returns (uint256 __r) { oldBasefee = __r; } catch { return; }
        bytes32 oldHash;
        try c.hash() returns (bytes32 __r) { oldHash = __r; } catch { return; }
        uint64 oldSequenceNumber;
        try c.sequenceNumber() returns (uint64 __r) { oldSequenceNumber = __r; } catch { return; }
