        uint256 oldL1FeeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { oldL1FeeOverhead = __r; } catch { return; }
        uint256 oldL1FeeScalar;
        try c.l1FeeScalar() returns (uint256 __r) { oldL1FeeScalar = __r; } catch { return; }
